"""CLI entry point for csvstat."""

import argparse
import sys
from typing import Any

from csvstat import formatting, reader, stats


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="csvstat")
    subparsers = parser.add_subparsers(dest="command", required=True)

    # describe FILE [--delimiter D] [--format FMT]
    desc_parser = subparsers.add_parser("describe")
    desc_parser.add_argument("FILE")
    desc_parser.add_argument("--delimiter", default=",")
    desc_parser.add_argument("--format", choices=["text", "json"], default="text")

    # col FILE NAME [--delimiter D] [--format FMT]
    col_parser = subparsers.add_parser("col")
    col_parser.add_argument("FILE")
    col_parser.add_argument("NAME")
    col_parser.add_argument("--delimiter", default=",")
    col_parser.add_argument("--format", choices=["text", "json"], default="text")

    # top FILE NAME --n K [--delimiter D]
    top_parser = subparsers.add_parser("top")
    top_parser.add_argument("FILE")
    top_parser.add_argument("NAME")
    top_parser.add_argument("--n", type=int, required=True)
    top_parser.add_argument("--delimiter", default=",")

    return parser


def _describe(args: argparse.Namespace) -> None:
    headers, rows = reader.read_csv(args.FILE, args.delimiter)
    columns: list[dict[str, Any]] = []
    for i, name in enumerate(headers):
        values = [row[i] if i < len(row) else "" for row in rows]
        if stats.is_numeric(values):
            ns = stats.numeric_stats(values)
            columns.append({
                "name": name,
                "type": "numeric",
                **ns,
            })
        else:
            cs = stats.categorical_stats(values)
            columns.append({
                "name": name,
                "type": "categorical",
                **cs,
            })
    if args.format == "json":
        print(formatting.format_json(columns))
    else:
        print(formatting.format_table(columns))


def _col(args: argparse.Namespace) -> None:
    headers, rows = reader.read_csv(args.FILE, args.delimiter)
    if args.NAME not in headers:
        print(f"Error: column '{args.NAME}' not found", file=sys.stderr)
        sys.exit(1)
    i = headers.index(args.NAME)
    values = [row[i] if i < len(row) else "" for row in rows]
    if stats.is_numeric(values):
        ns = stats.numeric_stats(values)
        col_dict: dict[str, Any] = {
            "name": args.NAME,
            "type": "numeric",
            **ns,
        }
    else:
        cs = stats.categorical_stats(values)
        col_dict = {
            "name": args.NAME,
            "type": "categorical",
            **cs,
        }
    if args.format == "json":
        print(formatting.format_json([col_dict]))
    else:
        print(formatting.format_table([col_dict]))


def _top(args: argparse.Namespace) -> None:
    headers, rows = reader.read_csv(args.FILE, args.delimiter)
    if args.NAME not in headers:
        print(f"Error: column '{args.NAME}' not found", file=sys.stderr)
        sys.exit(1)
    i = headers.index(args.NAME)
    values = [row[i] if i < len(row) else "" for row in rows]
    result = stats.top_values(values, args.n)
    for value, count in result:
        print(f"{value}: {count}")


def main() -> None:
    parser = _build_parser()
    args = parser.parse_args()

    if args.command == "describe":
        _describe(args)
    elif args.command == "col":
        _col(args)
    elif args.command == "top":
        _top(args)


if __name__ == "__main__":
    main()

